//! Exact-value DMRG tests (bug P6) through both executors.
//!
//! Expected energies are exact-diagonalisation values from numpy `eigvalsh`,
//! generated by `tests/refs/dmrg_ed.py`. They are never derived from DMRG
//! output. Bond dimension chi = 2^(n/2) is full rank, so DMRG must match ED.
//!
//!   dmrg_heisenberg: H = sum_i (X_i X_{i+1} + Y_i Y_{i+1} + Z_i Z_{i+1}), open
//!   dmrg_ising:      H = sum_i Z_i Z_{i+1}, open (ED ground energy -(n-1))

/// Run CJC source through eval, return output lines.
fn run_eval(src: &str, seed: u64) -> Vec<String> {
    let (program, _diag) = cjc_parser::parse_source(src);
    let mut interp = cjc_eval::Interpreter::new(seed);
    let _ = interp.exec(&program);
    interp.output
}

/// Run CJC source through MIR-exec, return output lines.
fn run_mir(src: &str, seed: u64) -> Vec<String> {
    let (program, _diag) = cjc_parser::parse_source(src);
    let (_, executor) = cjc_mir_exec::run_program_with_executor(&program, seed)
        .unwrap_or_else(|e| panic!("MIR-exec failed: {e}"));
    executor.output
}

/// Assert both executors produce identical output; return it.
fn assert_parity(src: &str) -> Vec<String> {
    let eval_out = run_eval(src, 42);
    let mir_out = run_mir(src, 42);
    assert_eq!(
        eval_out, mir_out,
        "Parity mismatch!\nEval: {eval_out:?}\nMIR:  {mir_out:?}"
    );
    eval_out
}

fn check(builtin: &str, n: usize, ed: f64) {
    let chi = 1usize << (n / 2);
    let src = format!("print({builtin}({n}, {chi}, 20, 1e-13));");
    let out = assert_parity(&src);
    assert_eq!(out.len(), 1, "{builtin} n={n}: expected one line, got {out:?}");
    let got: f64 = out[0].trim().parse().unwrap_or_else(|e| panic!("{out:?}: {e}"));
    let rel = ((got - ed) / ed).abs();
    assert!(
        rel <= 1e-10,
        "{builtin}({n}, {chi}): got {got:.17}, ED {ed:.17}, rel err {rel:.3e}"
    );
}

#[test]
fn dmrg_heisenberg_n4_matches_ed() {
    check("dmrg_heisenberg", 4, -6.464101615137755);
}

#[test]
fn dmrg_heisenberg_n6_matches_ed() {
    check("dmrg_heisenberg", 6, -9.974308535551705);
}

#[test]
fn dmrg_heisenberg_n8_matches_ed() {
    check("dmrg_heisenberg", 8, -13.499730394751575);
}

#[test]
fn dmrg_ising_matches_ed() {
    for n in [4usize, 6, 8] {
        check("dmrg_ising", n, -((n - 1) as f64));
    }
}

#[test]
fn dmrg_heisenberg_deterministic_across_runs() {
    let src = "print(dmrg_heisenberg(6, 8, 20, 1e-13));";
    let a = assert_parity(src);
    let b = assert_parity(src);
    assert_eq!(a, b, "DMRG output must be bit-identical across runs");
}
